// Sentientia LMS Live — audience SSE client — Phase E.3.b.
//
// Opens EventSource(stream.php?sessionid&token) and listens for:
//   slide_changed   -> reload page (so new slide renders fresh)
//   session_ended   -> reload page (shows the "session ended" panel)
//   response_added  -> dispatch CustomEvent for E.4 to attach a chart
//                       refresh handler (no innerHTML mutation here)
//   reconnect       -> let browser auto-reconnect; no action needed
//   sync (init)     -> first message after connect; verify state
//
// EventSource auto-reconnects with exponential backoff if the server
// closes, so we don't need our own retry logic. Browser also retains
// Last-Event-ID so we resume from where we left off after reconnect.
//
// Built with named-define ES5 for the bundled context (see PROJECT-STATE
// "AMD pipeline triple-bug fix" 2026-05-20 for why this matters).
define('local_sentientia_live/audience_sse', [], function() {
    'use strict';

    var POLL_FALLBACK_MS = 10000;

    function init(opts) {
        opts = opts || {};
        var sessionid = opts.sessionid;
        var token     = opts.token || '';
        // Default to M.cfg.wwwroot-prefixed URL so this works in any
        // Moodle deploy location (subfolder install vs root install).
        // M is a bare global in Moodle (not window.M), hence typeof guard.
        var wwwroot = (typeof M !== 'undefined' && M.cfg && M.cfg.wwwroot) ? M.cfg.wwwroot : '';
        var streamUrl = opts.streamUrl || (wwwroot + '/local/sentientia_live/stream.php');

        if (!sessionid) {
            console.warn('[sentientia_live] no sessionid — falling back to polling');
            setTimeout(function() { window.location.reload(); }, POLL_FALLBACK_MS);
            return;
        }

        if (typeof window.EventSource === 'undefined') {
            console.warn('[sentientia_live] EventSource not supported — falling back to polling');
            setTimeout(function() { window.location.reload(); }, POLL_FALLBACK_MS);
            return;
        }

        var qs = 'sessionid=' + encodeURIComponent(sessionid);
        if (token) {
            qs += '&token=' + encodeURIComponent(token);
        }
        var url = streamUrl + '?' + qs;

        var es;
        try {
            es = new EventSource(url, {withCredentials: false});
        } catch (e) {
            console.error('[sentientia_live] EventSource construction failed', e);
            setTimeout(function() { window.location.reload(); }, POLL_FALLBACK_MS);
            return;
        }

        es.addEventListener('error', function(ev) {
            // EventSource auto-reconnects on transient errors.
            // CLOSED means the server actively refused (403/503) so
            // fall back to meta-refresh polling.
            if (es.readyState === EventSource.CLOSED) {
                console.warn('[sentientia_live] SSE closed — falling back to polling');
                setTimeout(function() { window.location.reload(); }, POLL_FALLBACK_MS);
            }
        });

        es.addEventListener('sync', function(ev) {
            try {
                var data = JSON.parse(ev.data);
                // If page rendered with a stale current_slide_id (user
                // lingered while trainer advanced), reload to catch up.
                var domSlideId = parseInt(
                    document.body.dataset.currentSlideId || '0', 10);
                if (data.current_slide && data.current_slide !== domSlideId) {
                    window.location.reload();
                }
            } catch (e) { /* ignore parse errors */ }
        });

        es.addEventListener('slide_changed', function(ev) {
            window.location.reload();
        });

        es.addEventListener('session_ended', function(ev) {
            window.location.reload();
        });

        // Response added — dispatch a DOM custom event so the
        // (Phase E.4) result-panel module can decide how to refresh
        // (DOM-build vs full reload). This module stays free of
        // innerHTML mutation entirely.
        es.addEventListener('response_added', function(ev) {
            try {
                var data = JSON.parse(ev.data);
                window.dispatchEvent(new CustomEvent(
                    'sentientia-live:response_added',
                    {detail: data}
                ));
            } catch (e) { /* ignore */ }
        });

        es.addEventListener('reconnect', function(ev) {
            // No-op; browser EventSource auto-reconnects.
        });

        // Expose handle for E.4 module to close cleanly if it wants.
        window.sentientiaLiveSSE = es;
    }

    return {
        init: init
    };
});
